    11	 * toActionResult
    12	 */
    13	
    14	import { ForbiddenActionError } from "@/actions/_lib/action-errors";
    15	import { withAction } from "@/actions/_lib/with-action";
    16	import { isEnabled } from "@/lib/feature-flags";
    17	import { can } from "@/lib/permissions";
    18	import { searchQuerySchema, type SearchQueryInput } from "@/schemas/search";
    19	import { buildFlagContext } from "@/server/services/feature-flag-service";
    20	import { getOrganizationSummary } from "@/server/services/organization-service";
    21	import { search, type SearchHit } from "@/server/services/search-service";
    22	import type { ActionResult } from "@/types/api";
    23	
    24	const run = withAction<typeof searchQuerySchema, SearchHit[]>(
    25	  searchQuerySchema,
    26	  async (raw, actor) => {
    27	    const input = raw as SearchQueryInput;
    28	
    29	    if (!can(actor, "org:read", { kind: "organization", orgId: input.orgId })) {
    30	      throw new ForbiddenActionError("org:read");
    31	    }
    32	
    33	    const { organization } = await getOrganizationSummary(actor, input.orgId);
    34	    const context = buildFlagContext(actor, organization);
    35	
    36	    const kinds = isEnabled("advanced_search", context)
    37	      ? input.kinds
    38	      : input.kinds.filter((kind) => kind === "issue");
    39	
    40	    const page = await search(actor, { ...input, kinds });
    41	    return [...page.items];
    42	  },
    43	  { requireOrg: true },
    44	);
    45	
    46	export async function searchAction(raw: unknown): Promise<ActionResult<SearchHit[]>> {
    47	  return run(raw);
    48	}
