     1	import type { OrgId, TenantScoped } from "@/types/common";
     2	import type { Actor } from "@/types/member";
     3	
     4	/**
     5	 * Multi-tenancy invariant helpers.
     6	 *
     7	 * Every repository query must be filtered by `org_id`, and every row that
     8	 * crosses a service boundary must be re-checked against the actor's org. These
     9	 * helpers are the only sanctioned way to express that — a hand-written
    10	 * `if (row.orgId !== actor.orgId)` is a review failure.
    11	 */
    12	
    13	export class TenantScopeError extends Error {
    14	  readonly code = "tenant_scope_violation" as const;
    15	
    16	  constructor(
    17	    readonly expectedOrgId: OrgId,
    18	    readonly actualOrgId: OrgId,
    19	  ) {
    20	    super(
    21	      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    22	    );
    23	    this.name = "TenantScopeError";
    24	  }
    25	}
    26	
    27	/** Throws unless `orgId` belongs to the actor's organization. */
    28	export function assertOrgScope(actor: Actor, orgId: OrgId): void {
    29	  if (actor.orgId !== orgId) {
    30	    throw new TenantScopeError(actor.orgId, orgId);
    31	  }
    32	}
    33	
    34	/** Throws unless every supplied row belongs to the actor's organization. */
    35	export function assertRowsInScope<T extends TenantScoped>(
    36	  actor: Actor,
    37	  rows: readonly T[],
    38	): void {
    39	  for (const row of rows) {
    40	    assertOrgScope(actor, row.orgId);
    41	  }
    42	}
    43	
    44	/** Non-throwing predicate, for filtering rather than failing. */
    45	export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
    46	  return row.orgId === actor.orgId;
    47	}
    48	
    49	/** Narrows a nullable row to one the actor may see; `null` otherwise. */
    50	export function scopedOrNull<T extends TenantScoped>(
    51	  actor: Actor,
    52	  row: T | null | undefined,
    53	): T | null {
    54	  if (!row) return null;
    55	  return row.orgId === actor.orgId ? row : null;
    56	}
    57	
    58	/**
    59	 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
    60	 * cannot forget it. Always spread the caller filter first.
    61	 */
    62	export function withOrgScope<T extends object>(
    63	  actor: Actor,
    64	  filter: T,
    65	): T & { orgId: OrgId } {
    66	  return { ...filter, orgId: actor.orgId };
    67	}
