  1	/**
  2	 * The `advanced_search` query language.
  3	 *
  4	 * A plain query is just terms. With the flag on, `kind:` and `project:`
  5	 * prefixes narrow the search before it reaches the index, which is why the
  6	 * parser lives on the client too: the dialog has to show the user what it
  7	 * understood before it spends a round trip.
  8	 */
  9	import type { ProjectId } from "@/types/common";
 10	
 11	export type SearchSubjectKind = "issue" | "comment" | "project";
 12	
 13	const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];
 14	
 15	export interface ParsedSearchQuery {
 16	  /** The free-text remainder, with every recognised token removed. */
 17	  readonly text: string;
 18	  readonly kinds: readonly SearchSubjectKind[];
 19	  readonly projectId: ProjectId | null;
 20	  /** Tokens that looked like syntax but named nothing we know. */
 21	  readonly unknownTokens: readonly string[];
 22	}
 23	
 24	export const DEFAULT_SEARCH_KINDS: readonly SearchSubjectKind[] = ["issue"];
 25	
 26	/**
 27	 * @param raw      what the user typed
 28	 * @param advanced whether the `advanced_search` flag is on for this org; when
 29	 *                 false the whole string is treated as free text so a colon in
 30	 *                 a title still finds the title.
 31	 */
 32	export function parseSearchQuery(
 33	  raw: string,
 34	  advanced: boolean,
 35	): ParsedSearchQuery {
 36	  if (!advanced) {
 37	    return {
 38	      text: raw.trim(),
 39	      kinds: DEFAULT_SEARCH_KINDS,
 40	      projectId: null,
 41	      unknownTokens: [],
 42	    };
 43	  }
 44	
 45	  const terms: string[] = [];
 46	  const kinds: SearchSubjectKind[] = [];
 47	  const unknown: string[] = [];
 48	  let projectId: ProjectId | null = null;
 49	
 50	  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
 51	    const separator = token.indexOf(":");
 52	    if (separator <= 0) {
 53	      terms.push(token);
 54	      continue;
 55	    }
 56	
 57	    const field = token.slice(0, separator).toLowerCase();
 58	    const value = token.slice(separator + 1);
 59	    if (value.length === 0) {
 60	      unknown.push(token);
 61	      continue;
 62	    }
 63	
 64	    if (field === "kind" || field === "in") {
 65	      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
 66	      if (KINDS.includes(kind)) kinds.push(kind);
 67	      else unknown.push(token);
 68	    } else if (field === "project") {
 69	      projectId = value as ProjectId;
 70	    } else {
 71	      unknown.push(token);
 72	    }
 73	  }
 74	
 75	  return {
 76	    text: terms.join(" "),
 77	    kinds: kinds.length > 0 ? kinds : DEFAULT_SEARCH_KINDS,
 78	    projectId,
 79	    unknownTokens: unknown,
 80	  };
 81	}
 82	
 83	/** A one-line explanation of what the parser understood, for the dialog. */
 84	export function describeQuery(parsed: ParsedSearchQuery): string {
 85	  const parts = [`searching ${parsed.kinds.join(", ")}`];
 86	  if (parsed.projectId !== null) parts.push(`in project ${parsed.projectId}`);
 87	  if (parsed.unknownTokens.length > 0) {
 88	    parts.push(`ignoring ${parsed.unknownTokens.join(", ")}`);
 89	  }
 90	  return parts.join(" · ");
 91	}
