 88	                  {hit.title}
 89	                </span>
 90	                <span className="mt-0.5 block text-sm text-slate-600">
 91	                  {hit.snippet}
 92	                </span>
 93	              </Link>
 94	            </li>
 95	          ))}
 96	        </ul>
 97	      )}
 98	    </div>
 99	  );
100	}
